          ev.preventDefault();
          ev.stopPropagation();
          if (ev.stopImmediatePropagation) ev.stopImmediatePropagation();
          window['$ponte'].apriGalleria(JSON.stringify(lista), indice);
        } catch (e) {}
      }, true);
    })();
    """.trimIndent()
